import json
def _reject_const(val):
    raise ValueError(f'Invalid constant: {val}')
for s in ['NaN', 'Infinity', '-Infinity', 'null', 'true', 'false', '123', '\"abc\"', '{\"a\": 1}', '[]', '{']:
    try:
        res = json.loads(s, parse_constant=_reject_const)
        print(s, '->', type(res), res)
    except Exception as e:
        print(s, '-> EXCEPTION:', type(e), e)
